import{_ as r,a as i,b as o,c as l}from"./chunks/x25-mega_pinouts_02.BuQmYzIz.js";import{_ as s,C as n,o as d,c as u,j as e,a as p,E as c,al as h}from"./chunks/framework.7vp1BMOE.js";const C=JSON.parse('{"title":"CUAV X25-MEGA","description":"","frontmatter":{},"headers":[],"relativePath":"ko/flight_controller/cuav_x25-mega.md","filePath":"ko/flight_controller/cuav_x25-mega.md"}'),m={name:"ko/flight_controller/cuav_x25-mega.md"};function b(g,t,f,P,A,_){const a=n("Badge");return d(),u("div",null,[t[0]||(t[0]=e("h1",{id:"cuav-x25-mega",tabindex:"-1"},[p("CUAV X25-MEGA "),e("a",{class:"header-anchor",href:"#cuav-x25-mega","aria-label":'Permalink to "CUAV X25-MEGA"'},"​")],-1)),c(a,{type:"tip",text:"PX4 v1.18"}),t[1]||(t[1]=h('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://store.cuav.net/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The <em>X25-MEGA</em> is an advanced autopilot manufactured by CUAV<sup>®</sup>.</p><p>The autopilot is recommended for commercial system integration but is also suitable for academic research and any other applications.</p><p><img src="'+r+'" alt="X25-MEGA AutoPilot - hero image"></p><p>The X25-MEGA brings you ultimate performance, stability, and reliability in every aspect.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>이 비행 컨트롤러는 <a href="./../flight_controller/autopilot_manufacturer_supported">제조업체에서 지원</a>합니다.</p></div><h3 id="특징" tabindex="-1">특징 <a class="header-anchor" href="#특징" aria-label="Permalink to &quot;특징&quot;">​</a></h3><ul><li>Arm® Cortex-M7® processor (STM32H743XI) with Floating-Point Unit (FPU), operating at 480MHz, and featuring 2MB Flash memory. Enables developers to enhance productivity and efficiency, allowing for more complex algorithms and models.</li><li>Automotive-grade RM3100 compass. Designed for better stability and anti-interference capability.</li><li>Triple-redundant IMUs and dual-redundant barometers located on separate buses. If the PX4 autopilot detects a sensor failure, the system seamlessly switches to another sensor to maintain flight control reliability.</li><li>Independent LDO power control supplies power to each sensor group. A vibration isolation system filters high-frequency vibrations and reduces noise to ensure accurate readings, enabling better overall flight performance for the vehicle.</li><li>Integrated Microchip Ethernet PHY for high-speed communication with onboard devices like mission computers via Ethernet.</li><li>Dual temperature compensation systems, located on the IMU board and FMU board respectively. Temperature is controlled by onboard heating resistors to achieve the optimal operating temperature for the IMUs.</li><li>PWM servo output voltage switchable between 3.3V or 5V.</li><li>Modular design for DIY carrier boards.</li></ul><h3 id="processors-sensors" tabindex="-1">Processors &amp; Sensors <a class="header-anchor" href="#processors-sensors" aria-label="Permalink to &quot;Processors &amp; Sensors&quot;">​</a></h3><ul><li>Main Processor: STM32H743XI <ul><li>32-bit Arm® Cortex®-M7, 480MHz, 2MB Flash, 1MB RAM</li></ul></li><li>Onboard Sensors: <ul><li>Accel/Gyro: ADIS16607</li><li>Accel/Gyro: IIM42652</li><li>Accel/Gyro: IIM42653</li><li>자력계 : RM3100</li><li>Barometer: BMP581</li><li>Barometer: ICP-20100</li></ul></li></ul><h3 id="전기-데이터" tabindex="-1">전기 데이터 <a class="header-anchor" href="#전기-데이터" aria-label="Permalink to &quot;전기 데이터&quot;">​</a></h3><ul><li>Rated Voltage: <ul><li>Input Voltage: 10~18V</li><li>USB 전원 입력: 4.75~5.25V</li><li>Servo Rail Input: 0~9.9V</li></ul></li><li>Rated Current: <ul><li>Total Output Max Current: 10A</li><li><code>TELEM1</code> and <code>TELEM2</code> Output Current limiter: 4A</li><li><code>CAN1</code> and <code>CAN2</code> Output Current limiter: 2.4A</li><li>Other Ports Output Current limiter: 1.5A</li></ul></li></ul><h3 id="인터페이스" tabindex="-1">인터페이스 <a class="header-anchor" href="#인터페이스" aria-label="Permalink to &quot;인터페이스&quot;">​</a></h3><ul><li>16x PWM Servo Outputs</li><li>1x Dedicated R/C Input (<code>RC IN</code>) for Spektrum / DSM and S.Bus</li><li>1x Analog/PWM RSSI Input</li><li>2x TELEM Ports (with full flow control)</li><li>1x UART4 Port</li><li>2x GPS Ports <ul><li>1x Full GPS plus Safety Switch Port (GPS1)</li><li>1x Basic GPS Port (with I2C, GPS2)</li></ul></li><li>1x USB Port (TYPE-C)</li><li>1x Ethernet Port <ul><li>Transformerless application</li><li>100Mbps</li></ul></li><li>3x I2C Bus Ports</li><li>1x SPI Bus <ul><li>1x Chip Select Line</li><li>1x Data Ready Line</li><li>1x SPI Reset Line</li></ul></li><li>5x CAN Ports for CAN Peripherals <ul><li>3x CAN1 Bus Multiplexed Ports</li><li>2x CAN2 Bus Multiplexed Ports</li></ul></li><li>2x Power Input Ports <ul><li>DroneCAN/UAVCAN Power Input</li></ul></li><li>2x AD Ports <ul><li>Analog Input (3.3V)</li><li>Analog Input (6.6V - not supported)</li></ul></li><li>1x Dedicated Debug Port <ul><li>FMU Debug</li></ul></li></ul><h3 id="기계식-부품" tabindex="-1">기계식 부품 <a class="header-anchor" href="#기계식-부품" aria-label="Permalink to &quot;기계식 부품&quot;">​</a></h3><ul><li><p>Dimensions:</p><p><img src="'+i+'" alt="CUAV X25-MEGA"></p></li></ul><h2 id="store" tabindex="-1">Purchase Channels <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Purchase Channels {#store}&quot;">​</a></h2><p>Order from <a href="https://store.cuav.net/" target="_blank" rel="noreferrer">CUAV</a>.</p><h2 id="조립-및-설정" tabindex="-1">조립 및 설정 <a class="header-anchor" href="#조립-및-설정" aria-label="Permalink to &quot;조립 및 설정&quot;">​</a></h2><p>The <a href="./../assembly/quick_start_cuav_x25_evo">X25 MEGA Wiring Quick Start</a> provides instructions on how to assemble required/important peripherals including GPS, Power Module etc.</p><h2 id="핀배열" tabindex="-1">핀배열 <a class="header-anchor" href="#핀배열" aria-label="Permalink to &quot;핀배열&quot;">​</a></h2><p><img src="'+o+'" alt="CUAV X25-MEGA Pinout_01"><img src="'+l+'" alt="CUAV X25-MEGA Pinout_02"></p><h2 id="pwm_outputs" tabindex="-1">PWM Outputs <a class="header-anchor" href="#pwm_outputs" aria-label="Permalink to &quot;PWM Outputs {#pwm_outputs}&quot;">​</a></h2><p>This flight controller supports up to 16 FMU PWM outputs (MAIN).</p><p>Outputs:</p><ul><li>Outputs 1-8 support <a href="./../peripherals/dshot">DShot</a>.</li><li>Outputs 9-16 do not support DShot.</li><li>Outputs 1-7 support <a href="./../peripherals/dshot#bidirectional-dshot-telemetry">Bidirectional DShot</a>.</li><li>Output 8 supports Bidirectional DShot output only (no eRPM capture).</li></ul><p>The 16 outputs are in 5 groups:</p><ul><li>Outputs 1-4 in group1 (Timer5)</li><li>Outputs 5-8 in group2 (Timer4)</li><li>Outputs 9-11 in group3 (Timer1)</li><li>Outputs 12-14 in group4 (Timer8)</li><li>Outputs 15-16 in group5 (Timer12)</li></ul><p>All outputs within the same group must use the same output protocol and rate.</p><h2 id="시리얼-포트-매핑" tabindex="-1">시리얼 포트 매핑 <a class="header-anchor" href="#시리얼-포트-매핑" aria-label="Permalink to &quot;시리얼 포트 매핑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>장치</th><th>포트</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>GPS1</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>GPS2</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>디버그 콘솔</td></tr><tr><td>UART4</td><td>/dev/ttyS3</td><td>UART4</td></tr><tr><td>UART5</td><td>/dev/ttyS4</td><td>TELEM2</td></tr><tr><td>USART6</td><td>/dev/ttyS5</td><td>RC IN</td></tr><tr><td>UART7</td><td>/dev/ttyS6</td><td>TELEM1</td></tr></tbody></table><h2 id="rc-input" tabindex="-1">RC Input <a class="header-anchor" href="#rc-input" aria-label="Permalink to &quot;RC Input&quot;">​</a></h2><p>The RC input pin is directly connected to the FMU UART6 TX.</p><h2 id="정격-전압" tabindex="-1">정격 전압 <a class="header-anchor" href="#정격-전압" aria-label="Permalink to &quot;정격 전압&quot;">​</a></h2><p>The <em>X25-MEGA</em> achieves triple redundancy on power supplies if three power sources are provided. The three power rails are <code>POWER C1</code>, <code>POWER C2</code>, and <code>USB</code>.</p><ul><li><strong>POWER C1</strong> and <strong>POWER C2</strong> are DroneCAN/UAVCAN battery interfaces.</li></ul><p><strong>Normal Operation Maximum Ratings</strong></p><p>Under these conditions, all power sources will be used to power the system in the following order:</p><ol><li><strong>POWER C1</strong> and <strong>POWER C2</strong> Inputs (10V to 18V)</li><li>USB Input (4.75V to 5.25V)</li></ol><p><strong>Voltage monitoring</strong></p><p>Digital DroneCAN/UAVCAN battery monitoring is enabled by default.</p><h2 id="펌웨어-빌드" tabindex="-1">펌웨어 빌드 <a class="header-anchor" href="#펌웨어-빌드" aria-label="Permalink to &quot;펌웨어 빌드&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users will not need to build this firmware (from PX4 v1.18). It is pre-built and automatically installed by <em>QGroundControl</em> when appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target, execute:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cuav_x25-mega_default</span></span></code></pre></div><h2 id="debug_port" tabindex="-1">Debug Port <a class="header-anchor" href="#debug_port" aria-label="Permalink to &quot;Debug Port {#debug_port}&quot;">​</a></h2><p>The <a href="./../debug/system_console">PX4 System Console</a> and <a href="./../debug/swd_debug">SWD Interface</a> operate on the <strong>FMU Debug</strong> port.</p><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>5V+</td><td>+5V</td></tr><tr><td>2 (흑)</td><td>DEBUG TX(출력)</td><td>+3.3V</td></tr><tr><td>3 (흑)</td><td>DEBUG TX(입력)</td><td>+3.3V</td></tr><tr><td>4 (흑)</td><td>FMU_SWDIO</td><td>+3.3V</td></tr><tr><td>5 (흑)</td><td>FMU_SWCLK</td><td>+3.3V</td></tr><tr><td>6 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table><h2 id="지원-플랫폼-및-기체" tabindex="-1">지원 플랫폼 및 기체 <a class="header-anchor" href="#지원-플랫폼-및-기체" aria-label="Permalink to &quot;지원 플랫폼 및 기체&quot;">​</a></h2><p>일반 RC 서보 또는 Futaba S-Bus 서보로 제어 가능한 모든 멀티콥터/비행기/로버 또는 보트. The complete set of supported configurations can be seen in the <a href="./../airframes/airframe_reference">Airframes Reference</a>.</p><h2 id="추가-정보" tabindex="-1">추가 정보 <a class="header-anchor" href="#추가-정보" aria-label="Permalink to &quot;추가 정보&quot;">​</a></h2><ul><li><a href="https://doc.cuav.net/" target="_blank" rel="noreferrer">CUAV Docs</a></li></ul>',52))])}const v=s(m,[["render",b]]);export{C as __pageData,v as default};
